const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const error = (uuidPattern.test(sessionId) && uuidPattern.test(requestId))
  ? null
  : { code: 'INVALID_SESSION', message: 'Checking the Xero connection needs a valid conversation and request ID.' };
return [{ json: {
  valid: error === null, sessionId, requestId,
  proposedInput: { sessionId, requestId },
  ...(error ? { response: { ok: false, error } } : {}),
} }];

const raw = $input.first().json ?? {};
const status = Number(raw.statusCode ?? 0);
const body = raw.body ?? {};
const nodeError = String(raw.error?.message ?? raw.error ?? '');
const CONNECT_STEPS = "Open n8n at http://localhost:5678 | Open the credential named Xero (read-only). It may use either a standard Web app (Authorization Code) or a single-organisation Custom Connection (Client Credentials); docs/XERO_RECONCILIATION.md has both sets of fields. | For a standard connection, the permission screen must say view, never create, update, or delete. Complete Xero's own authorisation step. Never send a Xero password, verification code, or client secret through chat.";
const orgs = Array.isArray(body) ? body : [];
let state = 'unknown';
let message = '';
if (status === 200 && orgs.length > 0) { state = 'connected'; message = 'Xero is connected to ' + String(orgs[0].tenantName ?? 'the authorised organisation') + '.'; }
else if (status === 200) { state = 'not_connected'; message = 'The standard connection list is empty; checking whether this credential is a Custom Connection.'; }
else if (status === 401 || status === 403) { state = 'needs_reauth'; message = 'The standard Xero connection refused access; checking whether this credential is a Custom Connection. Standard refresh tokens can expire after 60 days without use.'; }
else if (!status || /credential/i.test(nodeError)) { state = 'not_connected'; message = 'There is no working Xero read-only credential yet.'; }
else { state = 'unknown'; message = 'The standard Xero connection check did not answer as expected (' + (status || 'no response') + ').'; }
return [{ json: { connected: state === 'connected', state, message, connectionType: state === 'connected' ? 'standard' : '', organisationName: state === 'connected' ? String(orgs[0].tenantName ?? '') : '', tenantId: state === 'connected' ? String(orgs[0].tenantId ?? '') : '', organisationCount: orgs.length, n8nUrl: 'http://localhost:5678', connectSteps: CONNECT_STEPS, scope: 'accounting.banktransactions.read accounting.invoices.read accounting.contacts.read accounting.settings.read' } }];

const raw = $input.first().json ?? {};
const status = Number(raw.statusCode ?? 0);
const body = raw.body ?? {};
const nodeError = String(raw.error?.message ?? raw.error ?? '');
const WRITE_CONNECT_STEPS = "This one is optional. Everything except preparing transactions works without it. | In n8n, Credentials, create a second credential of type OAuth2 API named exactly \"Xero (read-write)\", using the same Xero app as the first. | Set the Scope field to: offline_access accounting.banktransactions | Select Connect my account. This permission screen will say view AND update your business transactions. That difference is the whole point of the second credential, and you should never see those words on the read-only one.";

const orgs = Array.isArray(body) ? body : [];
let writeState = 'unknown';
if (status === 200 && orgs.length > 0) writeState = 'connected';
else if (status === 401 || status === 403) writeState = 'needs_reauth';
else if (!status || /credential/i.test(nodeError)) writeState = 'not_connected';

return [{ json: {
  writeState,
  writeConnected: writeState === 'connected',
  writeConnectSteps: WRITE_CONNECT_STEPS,
  writeScope: 'offline_access accounting.banktransactions',
} }];

const input = $('Validate Connection Input').first().json;
const fromNode = (name) => { try { return $(name).first().json; } catch { return null; } };
const probe = fromNode('Read Custom Probe') ?? fromNode('Read Xero Probe') ?? {};
const writeProbe = $input.first().json;
const NEXT = {
  connected: 'Tell the user which organisation it is connected to and whether it is a standard or Custom Connection. Nothing more is needed to start a review.',
  not_connected: 'Guide the user through the matching setup in docs/XERO_RECONCILIATION.md. The agent cannot complete the credential or authorisation steps for them. Never ask for a Xero password, verification code, or client secret.',
  needs_reauth: 'For a standard connection, reconnect the Xero (read-only) credential. For a Custom Connection, check that the app is authorised and regenerate its n8n credential only if the user chooses to.',
  unknown: 'Say it could not be checked right now and offer to try again. Do not reconfigure anything from one failed check.',
};
const WRITE_NEXT = { connected: 'The separate write credential is connected. Use it only after exact suggestions are accepted.', not_connected: 'The optional write credential is not set up. Mention it only if the user asks to create prepared transactions.', needs_reauth: 'The optional write credential needs reconnecting. Mention it only for preparation.', unknown: '' };
return [{ json: { ...input, response: { ok: true, connected: probe.connected, state: probe.state, connectionType: probe.connectionType || '', organisationName: probe.organisationName, tenantId: probe.tenantId, organisationCount: probe.organisationCount, multipleOrganisations: probe.organisationCount > 1, n8nUrl: probe.n8nUrl, connectSteps: probe.connectSteps, requiredScope: probe.scope, message: probe.message + (probe.organisationCount > 1 ? ' More than one organisation is authorised; reviews use the first one.' : ''), nextStep: NEXT[probe.state] ?? NEXT.unknown, writeConnected: writeProbe.writeConnected, writeState: writeProbe.writeState, writeConnectSteps: writeProbe.writeConnectSteps, writeScope: writeProbe.writeScope, writeNextStep: WRITE_NEXT[writeProbe.writeState] ?? '' } } }];

const input = $('Validate Connection Input').first().json;
const response = $json.response ?? { ok: false, error: { code: 'TOOL_FAILED', message: 'The tool did not return a result.' } };
return { json: {
  occurredAt: new Date().toISOString(),
  sessionId: input.sessionId,
  requestId: input.requestId,
  toolName: 'check_xero_connection',
  proposedInput: JSON.stringify(input.proposedInput ?? {}),
  result: JSON.stringify(response),
  error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '',
  response
} };

const prepared = $('Prepare Audit').first().json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };

const standard = $('Read Xero Probe').first().json;
const raw = $input.first().json ?? {};
const status = Number(raw.statusCode ?? 0);
const organisations = Array.isArray(raw.body?.Organisations) ? raw.body.Organisations : [];
if (status !== 200 || organisations.length === 0) return [{ json: standard }];
const organisation = organisations[0];
return [{ json: { ...standard, connected: true, state: 'connected', connectionType: 'custom', organisationName: String(organisation.Name ?? organisation.LegalName ?? ''), tenantId: String(organisation.OrganisationID ?? ''), organisationCount: 1, message: 'Xero Custom Connection is connected to ' + String(organisation.Name ?? organisation.LegalName ?? 'the authorised organisation') + '.' } }];
